<script setup lang="ts">import{computed,onBeforeUnmount,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{teacherAPI}from'../../api/teacher';import type{ApiKey}from'../../api/types';import{APIError}from'../../api/client';import StatusBadge from'../../components/StatusBadge.vue';import AppDialog from'../../components/AppDialog.vue';import{useToast}from'../../composables/useToast';const rows=ref<ApiKey[]>([]),selected=ref<ApiKey|null>(null),comment=ref(''),query=ref(''),organization=ref(''),project=ref(''),error=ref(''),confirmation=ref<'approve'|'reject'|null>(null),toast=useToast(),router=useRouter();const filtered=computed(()=>rows.value.filter(k=>(!query.value||`${k.applicant?.name} ${k.applicant?.email}`.toLowerCase().includes(query.value.toLowerCase()))&&(!organization.value||k.organization.id===organization.value)&&(!project.value||k.project.id===project.value)));const orgs=computed(()=>[...new Map(rows.value.map(k=>[k.organization.id,k.organization])).values()]),projects=computed(()=>[...new Map(rows.value.map(k=>[k.project.id,k.project])).values()]);const ready=computed(()=>Boolean(selected.value?.models.every(m=>m.status==='active'&&m.route_ready)));async function load(){try{rows.value=(await teacherAPI.keyReviews()).sort((a,b)=>a.created_at.localeCompare(b.created_at))}catch(e){error.value=msg(e)}}async function open(row:ApiKey){try{selected.value=await teacherAPI.keyReview(row.id);comment.value=''}catch(e){error.value=msg(e)}}async function act(){if(!selected.value||!confirmation.value)return;const approve=confirmation.value==='approve';if(!approve&&!comment.value.trim()){error.value='驳回必须填写原因';return}try{await teacherAPI.reviewKey(selected.value.id,approve,comment.value||undefined);toast.success(approve?'终审已通过':'申请已驳回');selected.value=null;confirmation.value=null;await load();if(rows.value[0])await open(rows.value[0])}catch(e){error.value=msg(e);if(e instanceof APIError&&e.code==='INVALID_STATE_TRANSITION'){selected.value=null;await load()}}}function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'}function refresh(){void load()};onMounted(()=>{void load();window.addEventListener('nebula:refresh',refresh)});onBeforeUnmount(()=>window.removeEventListener('nebula:refresh',refresh));</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">TEACHER</p><h1>审批密钥</h1><p class="muted">终审队列按最早提交优先，逐模型检查配置和路由。</p></div><button class="button secondary" @click="load">刷新</button></div><p v-if="error" class="error banner">{{error}}</p><section class="panel"><div class="grid two"><label>搜索申请人<input v-model="query" placeholder="姓名或邮箱"/></label><div class="row"><label>组织<select v-model="organization"><option value="">全部组织</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option></select></label><label>项目<select v-model="project"><option value="">全部项目</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div></div></section><div class="grid two" style="margin-top:20px"><section class="panel"><article v-for="key in filtered" :key="key.id" class="review-row"><div><strong>{{key.name}}</strong><p>{{key.applicant?.name}} · {{key.applicant?.email}}</p><p class="muted">{{key.organization.name}} · {{key.project.name}}</p></div><button class="button primary" @click="open(key)">终审</button></article><div v-if="!filtered.length" class="empty">暂无待终审申请</div></section><section class="panel"><template v-if="selected"><h2>{{selected.name}}</h2><p>{{selected.applicant?.name}}（{{selected.applicant?.email}}）</p><p>{{selected.organization.name}} · {{selected.project.name}}</p><h2>模型就绪检查</h2><article v-for="model in selected.models" :key="model.id" class="list-row"><div><strong>{{model.display_name}}</strong><p class="muted">{{model.model_id}} · 模型 {{model.status==='active'?'ACTIVE':'未 ACTIVE'}} · 路由 {{model.route_ready?'就绪':'未就绪'}}</p></div><div><StatusBadge :status="model.status"/><button v-if="model.status!=='active'||!model.route_ready" class="button ghost" @click="router.push(`/teacher/models?model=${model.id}`)">配置</button></div></article><h2>导师审核记录</h2><div v-for="audit in selected.audits" :key="audit.created_at" class="list-row"><span>{{audit.actor_role}} · {{audit.action}}</span><span>{{audit.comment||'无意见'}}</span></div><label>终审意见<textarea v-model="comment" rows="4" placeholder="驳回必填"/></label><div class="actions"><button class="button danger" @click="confirmation='reject'">驳回</button><button class="button primary" :disabled="!ready" @click="confirmation='approve'">终审通过</button></div></template><div v-else class="empty">选择申请查看终审摘要</div></section></div><AppDialog :open="Boolean(confirmation)" :title="confirmation==='approve'?'确认终审通过':'确认驳回'" @update:open="confirmation=$event?confirmation:null"><p>{{confirmation==='approve'?'通过后学生将加入组织和项目，Key 等待一次性领取。':'驳回原因将永久记录在审计中。'}}</p><div class="actions"><button class="button" :class="confirmation==='approve'?'primary':'danger'" @click="act">确认</button></div></AppDialog></section></template>
